#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    char *end1, *end2;
    errno = 0;
    long long a = strtoll(argv[1], &end1, 10);
    long long b = strtoll(argv[2], &end2, 10);

    if (errno != 0 || *end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    if (a < 0) a = -a;
    if (b < 0) b = -b;

    if (a > 1000000LL || b > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (a == 0 && b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    long long x = a, y = b;
    while (y != 0) {
        long long r = x % y;
        x = y;
        y = r;
    }
    long long gcd = x;
    long long lcm = (a / gcd) * b;

    printf("gcd=%lld lcm=%lld\n", gcd, lcm);
    return 0;
}
